// Explota perfiles[] x keywords[] en un item por combinacion (perfil, cv, keyword)
const cfg = $input.first().json;
const out = [];
for (const p of cfg.perfiles) {
  for (const kw of p.keywords) {
    out.push({ json: { perfil: p.perfil, cv: p.cv, keyword: kw, ubicacion: cfg.ubicacion, ubicacion_linkedin: cfg.ubicacion_linkedin, excluir_regex: cfg.excluir_regex } });
  }
}
return out;

// Seniority y stacks que no te sirven
const EXCLUIR_PUESTO = /(\b2\+?\s*a[nñ]os|\b3\s*a[nñ]os|senior|\bssr\b|semi[- ]s(enio)?r\b|c#|\.net\b|golang|\bgo\b|kubernetes|react native|qlik|\bsap\b|\bodoo\b|mainframe|racf|ingl[eé]s avanzado)/i;

// Gastronomia, hoteleria, comercio, seguridad y tareas operativas
const EXCLUIR_RUBRO = /(cocin|chef|bachero|lavacopas|mozo|moza|camarer|gastronom|restaurant|parrilla|pizzer|panader|confiter|helader|cafeter|barista|bartender|catering|sushi|delivery|repartidor|cadete|comida r[aá]pida|fast ?food|mostaza|burger|mcdonald|starbucks|subway|\bkfc\b|hotel|hoteler|mucama|housekeeping|sal[oó]n de fiestas|encargado de local|repositor|cajer|g[oó]ndola|supermercado|verduler|carnicer|kiosco|maestranza|vigilador|vigilancia|personal de limpieza|auxiliar de limpieza|operario de limpieza)/i;

// Solo CABA (descarta provincia y el resto del pais)
const ZONA_OK = /(capital federal|ciudad aut[oó]noma|\bcaba\b|buenos aires y alrededores)/i;

// Solo publicaciones de las ultimas 24hs (vacio = LinkedIn, que no manda fecha)
const FECHA_OK = /^$|ahora|hace\s+\d+\s*(minuto|hora)|ayer|hoy|hace\s+1\s*d[ií]a/i;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.url) continue;
  const texto = `${j.titulo} ${j.empresa} ${j.ubicacion}`;
  if (EXCLUIR_PUESTO.test(texto)) continue;
  if (EXCLUIR_RUBRO.test(texto)) continue;
  if (!ZONA_OK.test(j.ubicacion || '')) continue;
  if (!FECHA_OK.test((j.fecha_publicacion || '').trim())) continue;
  out.push({ json: j });
}
return out;

// Las ofertas vienen del nodo Filtrar, no de $input (que trae las filas de la planilla)
const filtradas = $('Filtrar (descartar dealbreakers)').all();

// URLs que ya estan guardadas en la planilla
// URLs ya guardadas con un match valido -> se saltean.
// Las que quedaron con un error transitorio de la IA (ats_tip empieza con "ERROR")
// NO se excluyen, para que la proxima corrida las vuelva a evaluar en vez de perderlas para siempre.
const existentes = new Set(
  $('Leer URLs ya guardadas').all()
    .filter(i => i.json.url && !String(i.json.ats_tip || '').startsWith('ERROR'))
    .map(i => i.json.url)
);

// URLs ya vistas en ESTA misma corrida (evita duplicados cuando 2 keywords matchean la misma oferta)
const sd = $getWorkflowStaticData('global');
if (!sd.urlsEstaCorrida) sd.urlsEstaCorrida = [];
const vistasEstaCorrida = new Set(sd.urlsEstaCorrida);

const nuevas = [];
for (const item of filtradas) {
  const url = item.json.url;
  if (!url) continue;
  if (existentes.has(url) || vistasEstaCorrida.has(url)) continue;
  vistasEstaCorrida.add(url);
  nuevas.push(item);
}
sd.urlsEstaCorrida = Array.from(vistasEstaCorrida);

return nuevas;

const ctx = $('Loop (rate limit)').item.json;
const html = $input.first().json.data || $input.first().json.body || '';

function decodeEntities(str) {
  return str
    .replace(/&#x([0-9A-Fa-f]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'");
}
function stripTags(str) {
  return decodeEntities(str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim());
}
function pick(block, re) {
  const m = block.match(re);
  return m ? stripTags(m[1]) : '';
}

const out = [];
for (const block of html.split('<li>').slice(1)) {
  const urlM = block.match(/href="(https:\/\/[^"]*\/jobs\/view\/[^"]+)"/);
  if (!urlM) continue;
  const titulo = pick(block, /base-search-card__title[^>]*>([\s\S]*?)</);
  const empresa = pick(block, /hidden-nested-link[^>]*>([\s\S]*?)<\/a>/)
               || pick(block, /base-search-card__subtitle[^>]*>([\s\S]*?)</);
  const ubicacion = pick(block, /job-search-card__location[^>]*>([\s\S]*?)</);
  if (!titulo) continue;
  out.push({ json: {
    fuente: 'LinkedIn', titulo, empresa, ubicacion, fecha_publicacion: '',
    url: decodeEntities(urlM[1]).split('?')[0],
    perfil: ctx.perfil, cv: ctx.cv, keyword: ctx.keyword
  }});
}
return out;

// Procesa TODO el batch que entrega 'Loop match IA' en paralelo (Promise.all),
// en vez de una oferta a la vez. Cada oferta: trae la descripcion, arma el prompt,
// llama a OpenCode Go (con 1 reintento) y devuelve match_pct + ats_tip.
// Si la IA falla las dos veces, nunca pisa un match_pct bueno que ya existiera.
const cfg = $('Config (perfiles + criterios)').first().json;

async function procesarOferta(ctx) {
  const cvBase = (cfg.cvs_base && cfg.cvs_base[ctx.perfil]) || '';

  // 1) Traer la descripcion completa de la oferta (si falla, seguimos solo con el titulo)
  let raw = '';
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: ctx.url,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
        'Accept-Language': 'es-AR,es;q=0.9,en;q=0.8',
        'Referer': 'https://www.google.com/',
        'Upgrade-Insecure-Requests': '1',
        'Connection': 'keep-alive'
      }
    });
    raw = (resp && (resp.body || resp.data)) || resp || '';
  } catch (e) {
    raw = '';
  }

  let desc = String(raw)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 4000);
  if (desc.length < 100) desc = '(no se pudo leer la descripcion completa, evaluar solo con el titulo)';

  const prompt = [
    'Sos un evaluador de compatibilidad entre un CV y una oferta laboral.',
    'Devolve SOLAMENTE un JSON valido, en una sola linea, sin markdown y sin backticks, con este formato exacto:',
    '{"match": <numero entero 0-100>, "tip": "<max 15 palabras: que keyword de la oferta conviene sumar o resaltar en el CV>"}',
    '',
    '=== CV DEL CANDIDATO ===',
    cvBase,
    '',
    '=== OFERTA ===',
    'Puesto: ' + (ctx.titulo || ''),
    'Empresa: ' + (ctx.empresa || ''),
    'Descripcion: ' + desc
  ].join('\n');

  // 2) Pedirle el match a la IA, con 1 reintento si la primera falla
  let texto = '';
  let goErr = '';
  for (let intento = 0; intento < 2 && !texto; intento++) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://opencode.ai/zen/go/v1/messages',
        headers: {
          'x-api-key': cfg.opencode_api_key,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        body: {
          model: 'minimax-m3',
          max_tokens: 300,
          messages: [{ role: 'user', content: prompt }]
        },
        json: true
      });
      texto = (resp.content || [])
        .filter(c => c.type === 'text')
        .map(c => c.text || '')
        .join('')
        .trim();
      if (!texto) goErr = 'Go sin texto: ' + JSON.stringify(resp).slice(0, 200);
    } catch (e) {
      goErr = (e.message || String(e)).slice(0, 200);
    }
  }

  let match_pct = (ctx.match_pct !== undefined && ctx.match_pct !== null && ctx.match_pct !== '') ? ctx.match_pct : '';
  let ats_tip = ctx.ats_tip || '';

  if (texto) {
    try {
      const jm = texto.match(/\{[\s\S]*\}/);
      const parsed = JSON.parse(jm ? jm[0] : texto);
      if (parsed.match !== undefined && parsed.match !== null) {
        match_pct = Number(parsed.match);
        ats_tip = parsed.tip || '';
      }
    } catch (e) {
      // no se pudo interpretar la respuesta: dejamos lo que ya habia
    }
  } else if (match_pct === '') {
    ats_tip = 'ERROR Go: ' + goErr;
  }

  const out = { ...ctx };
  out.match_pct = match_pct;
  out.ats_tip = ats_tip;
  return out;
}

const items = $input.all().map(i => i.json);
const resultados = await Promise.all(items.map(ctx => procesarOferta.call(this, ctx)));
return resultados.map(json => ({ json }));
